#!/bin/bash
set -Eeuo pipefail
export KUBECONFIG=/etc/rancher/k3s/k3s.yaml
kubectl -n argocd create secret generic cosmotech-gitops --from-literal=type=git --from-literal=url=ssh://git@ssh.github.com:443/rlcosmo/cosmotech-gitops.git --from-file=sshPrivateKey=/opt/cosmotech/argocd/github-deploy-key --dry-run=client -o yaml | kubectl apply -f -
kubectl -n argocd label secret cosmotech-gitops argocd.argoproj.io/secret-type=repository --overwrite
printf '%s' '' | base64 -d | kubectl apply -f -
printf '%s' '' | base64 -d | kubectl apply -f -
